// Visible Session Volume Value Model
// Volume-profile-on-chart: POC + value-area expansion, price leaving value is the signal.

rows = input(24, "Rows", 10, 48, 1)
vaPct = input(70.0, "Value Area Percent", 50.0, 90.0, 5.0)
showVA = input(true, "Show Value Area")
showPOC = input(true, "Show POC Rail")
use3D = input(true, "Use 3D Terrain")
markerSize = input(1.0, "Marker Size", 0.2, 3.0, 0.1)

// ─── Visible session range (whole loaded history = visible session) ───
sessLen = bar_index + 1
hh = highest(high, sessLen)
ll = lowest(low, sessLen)
rng = hh - ll
if rng <= 0 { rng := close * 0.01 }
rowH = rng / rows

// ─── Persistent volume-at-price rows ───
var binVol = array()
if array.size(binVol) == 0 {
    k = 0
    while k < 24 {
        array.push(binVol, 0.0)
        k := k + 1
    }
}

binIdx = floor((close - ll) / rng * rows)
if binIdx < 0 { binIdx := 0 }
if binIdx > rows - 1 { binIdx := rows - 1 }
curV = array.get(binVol, binIdx)
array.set(binVol, binIdx, curV + volume)

// ─── Point of control ───
pocBin = 0
pocVal = array.get(binVol, 0)
j = 1
while j < rows {
    v = array.get(binVol, j)
    if v > pocVal {
        pocVal := v
        pocBin := j
    }
    j := j + 1
}
totalVol = array.sum(binVol)
pocPrice = ll + (pocBin + 0.5) * rowH

// ─── Value area: expand from POC ───
vaLow = pocBin
vaHigh = pocBin
accum = pocVal
target = totalVol * vaPct / 100
guard = 0
while accum < target and guard < rows {
    leftVal = 0 - 1.0
    if vaLow > 0 { leftVal := array.get(binVol, vaLow - 1) }
    rightVal = 0 - 1.0
    if vaHigh < rows - 1 { rightVal := array.get(binVol, vaHigh + 1) }
    if rightVal >= leftVal and vaHigh < rows - 1 {
        vaHigh := vaHigh + 1
        accum := accum + rightVal
    } else {
        if vaLow > 0 {
            vaLow := vaLow - 1
            accum := accum + leftVal
        }
    }
    guard := guard + 1
}
vaHighPrice = ll + (vaHigh + 1) * rowH
vaLowPrice = ll + vaLow * rowH
insideVA = close >= vaLowPrice and close <= vaHighPrice
vaWidth = vaHighPrice - vaLowPrice
pocShare = 0.0
if totalVol > 0 { pocShare := pocVal / totalVol * 100 }
terrainSrc = pocVal + vaWidth * 0.001 + close * 0.001

// ─── Signals: price leaving value ───
wasInside = insideVA[1]
buySig = close > vaHighPrice and wasInside and crossover(close, vaHighPrice)
sellSig = close < vaLowPrice and wasInside and crossunder(close, vaLowPrice)

if buySig { plotshape(bar_index, low, "Buy", "triangleup", "#22cc88") }
if sellSig { plotshape(bar_index, high, "Sell", "triangledown", "#ff4477") }
if buySig { plotshape_3d(bar_index, low, "Buy", "coneup", "#22cc88", 1.0 * markerSize, 0, "3d") }
if sellSig { plotshape_3d(bar_index, high, "Sell", "conedown", "#ff4477", 1.0 * markerSize, 1, "3d") }
if buySig { model.longEntry("BuyBreak") }
if sellSig { model.shortEntry("SellBreak") }

// ─── Value area zone box (updates in place) ───
if showVA { box.new(bar_index - sessLen + 1, vaHighPrice, bar_index, vaLowPrice, "#22cc88", "rgba(34,204,136,0.08)", 1, "vazone") }
if showPOC { line.new(bar_index - sessLen + 1, pocPrice, bar_index, pocPrice, "#ffd43b", 2, "solid", false, "pocline") }
if showVA { line.new(bar_index - sessLen + 1, vaHighPrice, bar_index, vaHighPrice, "#22cc88", 1, "dashed", false, "vahline") }
if showVA { line.new(bar_index - sessLen + 1, vaLowPrice, bar_index, vaLowPrice, "#ff4477", 1, "dashed", false, "valline") }
if showPOC { text.new(bar_index, pocPrice, "POC", "#ffd43b", 1, "poclab") }
if showVA { text.new(bar_index, vaHighPrice, "VAH", "#22cc88", 1, "vah lab") }
if showVA { text.new(bar_index, vaLowPrice, "VAL", "#ff4477", 1, "vallab") }
if buySig { label3d(bar_index, vaHighPrice, "BREAKOUT", "#22cc88", 1.0, 1, "3d") }
if sellSig { label3d(bar_index, vaLowPrice, "BREAKDOWN", "#ff4477", 1.0, 2, "3d") }
if showPOC { label3d(bar_index, pocPrice, "POC", "#ffd43b", 1.2, 0, "3d") }

// ─── 2D: same information when 3D is off ───
plot(pocPrice, "POC", "#ffd43b", 2, "stepline")
plot(vaHighPrice, "Value Area High", "#22cc88", 1, "stepline")
plot(vaLowPrice, "Value Area Low", "#ff4477", 1, "stepline")
plot(close, "Price", "#ffffff", 1)
plot(pocShare, "POC Share %", "#b48cff", 1, "separate")

// ─── 3D: value terrain + POC labelled rail + VA edge rails ───
plot3d(terrainSrc, "Value Terrain", "surface", "#22cc88", "3d", 3)
plot3d(pocPrice, "POC Rail", "line3d", "#ffd43b", "3d", 0)
plot3d(vaHighPrice, "VAH Rail", "line3d", "#22cc88", "3d", 1)

// Fix 1: var lvl = highest(high, 20) froze at bar 0 — changed to plain assignment so it recomputes every bar.
// Fix 2: close[-1] peeked one bar into the future — changed to close so the breakout uses only confirmed price.
// Fix 3: plotshape(true, low, "Buy", shape.triangleup, color.green) was Pine signature — changed to OakScript positional (bar_index, price, title, style, color) with quoted style and hex color.
// Fix 4: plot3d(r, "RSI", "surface", "#b48cff", "3d") forced an oscillator into pane 3d — changed to pane "separate" per PANE LAW.
// Fix 5: missing 2D twin for RSI left 3D-only rendering — added top-level plot() so the model renders in both 2D and 3D modes.
lvlLen = input(20, "Level Length", 1, 100, 1)
rsiLen = input(14, "RSI Length", 1, 100, 1)
lvl = highest(high, lvlLen)
r = rsi(close, rsiLen)
buySig = close > lvl
osSig = crossover(r, 30)
if buySig {
    plotshape(bar_index, low, "Buy", "triangleup", "#22cc88")
}
if osSig {
    plotshape(bar_index, low, "OS", "triangleup", "#22cc88")
}
plot(r, "RSI", "#b48cff", 1, "line")
plot3d(r, "RSI", "surface", "#b48cff", "separate")
